mapper.select:
select t.person_name,t.person_name personName,t.sl_id,t.sl_id slId,t.machine_id,t.machine_id machineId,t.sms_content,t.sms_content
smsContent,t.tel,t.person_id,t.person_id personId,t.status_cd,t.status_cd
statusCd,t.state,t.community_id,t.community_id communityId,t.call_type,t.call_type callType,t.create_time createTime
from tel_sms_log t
where 1 =1

    and t.person_name= #{personName}


    and t.sl_id= #{slId}



    and t.machine_id= #{machineId}


    and t.sms_content= #{smsContent}


    and t.tel= #{tel}


    and t.person_id= #{personId}


    and t.status_cd= #{statusCd}


    and t.state= #{state}


    and t.community_id= #{communityId}


    and t.call_type= #{callType}

order by t.create_time desc

    limit #{page}, #{row}

